class Solution {

    /**
     * @param Integer $n
     * @return Integer
     */
    function minSteps($n) {
        $steps = 0;

        for ($factor = 2; $factor * $factor <= $n; $factor++) {
            while ($n % $factor === 0) {
                $steps += $factor;
                $n = intdiv($n, $factor);
            }
        }

        if ($n > 1) {
            $steps += $n;
        }

        return $steps;
    }
}
