    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Boolean
     */
    function kLengthApart($nums, $k) {
        $previous = -$k - 1;

        foreach ($nums as $index => $value) {
            if ($value === 1) {
                if ($index - $previous - 1 < $k) {
                    return false;
