<?php

class Solution {

    /**
     * @param Integer[][] $grid
     * @param Integer[][] $hits
     * @return Integer[]
     */
    function hitBricks($grid, $hits) {
        $m = count($grid);
        $n = count($grid[0]);
        $roof = $m * $n;
        $total = $roof + 1;

        $state = $grid;
        $hitCount = count($hits);
        $removed = array_fill(0, $hitCount, false);

        for ($i = 0; $i < $hitCount; $i++) {
            $r = $hits[$i][0];
            $c = $hits[$i][1];

            if ($state[$r][$c] === 1) {
                $removed[$i] = true;
                $state[$r][$c] = 0;
            }
        }

        $parent = range(0, $total - 1);
        $size = array_fill(0, $total, 1);

        for ($r = 0; $r < $m; $r++) {
            for ($c = 0; $c < $n; $c++) {
                if ($state[$r][$c] !== 1) {
                    continue;
                }

                $id = $r * $n + $c;

                if ($r === 0) {
                    $this->unite($parent, $size, $id, $roof);
                }

                if ($r > 0 && $state[$r - 1][$c] === 1) {
                    $this->unite($parent, $size, $id, ($r - 1) * $n + $c);
                }

                if ($c > 0 && $state[$r][$c - 1] === 1) {
                    $this->unite($parent, $size, $id, $r * $n + $c - 1);
                }
            }
        }

        $result = array_fill(0, $hitCount, 0);
        $directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];

        for ($i = $hitCount - 1; $i >= 0; $i--) {
            if (!$removed[$i]) {
                continue;
            }

            $r = $hits[$i][0];
            $c = $hits[$i][1];
            $before = $size[$this->find($parent, $roof)];

            $state[$r][$c] = 1;
            $id = $r * $n + $c;

            if ($r === 0) {
                $this->unite($parent, $size, $id, $roof);
            }

            foreach ($directions as $direction) {
                $nr = $r + $direction[0];
                $nc = $c + $direction[1];

                if (
                    $nr >= 0 && $nr < $m &&
                    $nc >= 0 && $nc < $n &&
                    $state[$nr][$nc] === 1
                ) {
                    $this->unite($parent, $size, $id, $nr * $n + $nc);
                }
            }

            $after = $size[$this->find($parent, $roof)];
            $result[$i] = max(0, $after - $before - 1);
        }

        return $result;
    }

    private function find(&$parent, $x) {
        while ($parent[$x] !== $x) {
            $parent[$x] = $parent[$parent[$x]];
            $x = $parent[$x];
        }

        return $x;
    }

    private function unite(&$parent, &$size, $a, $b) {
        $rootA = $this->find($parent, $a);
        $rootB = $this->find($parent, $b);

        if ($rootA === $rootB) {
            return;
        }

        if ($size[$rootA] < $size[$rootB]) {
            $temp = $rootA;
            $rootA = $rootB;
            $rootB = $temp;
        }

        $parent[$rootB] = $rootA;
        $size[$rootA] += $size[$rootB];
    }
}
