class Solution {

    /**
     * @param Integer[] $stones
     * @return Boolean
     */
    function canCross($stones) {
        $n = count($stones);

        if ($stones[1] !== 1) {
            return false;
        }

        if ($n === 2) {
            return true;
        }

        $positionToIndex = [];
        foreach ($stones as $index => $position) {
            $positionToIndex[$position] = $index;

            if ($index > 0 && $position - $stones[$index - 1] > $index) {
                return false;
            }
        }

        $reachable = array_fill(0, $n, []);
        $reachable[1][1] = true;
        $target = $stones[$n - 1];

        for ($i = 1; $i < $n; $i++) {
            foreach ($reachable[$i] as $lastJump => $_) {
                for ($jump = $lastJump - 1; $jump <= $lastJump + 1; $jump++) {
                    if ($jump <= 0) {
                        continue;
                    }

                    $nextPosition = $stones[$i] + $jump;

                    if ($nextPosition === $target) {
                        return true;
                    }

                    if (isset($positionToIndex[$nextPosition])) {
                        $nextIndex = $positionToIndex[$nextPosition];
                        $reachable[$nextIndex][$jump] = true;
                    }
                }
