class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer $numSlots
     * @return Integer
     */
    function maximumANDSum($nums, $numSlots) {
        $powersOfThree = array_fill(0, $numSlots + 1, 1);

        for ($i = 1; $i <= $numSlots; $i++) {
            $powersOfThree[$i] = $powersOfThree[$i - 1] * 3;
        }

        $stateCount = $powersOfThree[$numSlots];
        $dp = array_fill(0, $stateCount, -1);
        $dp[0] = 0;

        foreach ($nums as $number) {
            $next = array_fill(0, $stateCount, -1);

            for ($state = 0; $state < $stateCount; $state++) {
                if ($dp[$state] < 0) {
                    continue;
                }

                for ($slot = 0; $slot < $numSlots; $slot++) {
                    $occupancy = intdiv($state, $powersOfThree[$slot]) % 3;

                    if ($occupancy < 2) {
                        $newState = $state + $powersOfThree[$slot];
                        $score = $dp[$state] + ($number & ($slot + 1));

                        if ($score > $next[$newState]) {
                            $next[$newState] = $score;
                        }
                    }
                }
            }

            $dp = $next;
        }

        return max($dp);
    }
}
