    function maxTotalFruits($fruits, $startPos, $k) {
        $left = 0;
        $sum = 0;
        $answer = 0;
        $n = count($fruits);

        for ($right = 0; $right < $n; $right++) {
            $sum += $fruits[$right][1];

            while ($left <= $right) {
                $leftPos = $fruits[$left][0];
                $rightPos = $fruits[$right][0];

                if ($rightPos <= $startPos) {
                    $steps = $startPos - $leftPos;
                } elseif ($leftPos >= $startPos) {
                    $steps = $rightPos - $startPos;
                } else {
                    $leftDistance = $startPos - $leftPos;
                    $rightDistance = $rightPos - $startPos;
                    $steps = min(
                        2 * $leftDistance + $rightDistance,
                        $leftDistance + 2 * $rightDistance
                    );
