    function licenseKeyFormatting($s, $k) {
        $clean = strtoupper(str_replace('-', '', $s));
        $length = strlen($clean);

        if ($length === 0) {
            return '';
        }

        $firstGroupLength = $length % $k;
        if ($firstGroupLength === 0) {
            $firstGroupLength = $k;
        }

        $groups = [substr($clean, 0, $firstGroupLength)];

        for ($i = $firstGroupLength; $i < $length; $i += $k) {
            $groups[] = substr($clean, $i, $k);
        }

        return implode('-', $groups);
