class Solution {

    /**
     * @param Integer[] $flowers
     * @param Integer $newFlowers
     * @param Integer $target
     * @param Integer $full
     * @param Integer $partial
     * @return Integer
     */
    function maximumBeauty($flowers, $newFlowers, $target, $full, $partial) {
        $n = count($flowers);
        $incomplete = [];
        $alreadyFull = 0;

        foreach ($flowers as $count) {
            if ($count >= $target) {
                $alreadyFull++;
            } else {
                $incomplete[] = $count;
            }
        }

        $m = count($incomplete);

        if ($m === 0) {
            return $n * $full;
        }

        sort($incomplete, SORT_NUMERIC);

        $prefix = array_fill(0, $m + 1, 0);
        for ($i = 0; $i < $m; $i++) {
            $prefix[$i + 1] = $prefix[$i] + $incomplete[$i];
        }

        $answer = 0;
        $completionCost = 0;

        for ($completed = 0; $completed <= $m; $completed++) {
            if ($completionCost > $newFlowers) {
                break;
            }

            $remainingBudget = $newFlowers - $completionCost;
            $remaining = $m - $completed;
            $beauty = ($alreadyFull + $completed) * $full;

            if ($remaining > 0) {
                $low = 1;
                $high = $remaining;

                while ($low < $high) {
                    $mid = intdiv($low + $high + 1, 2);
                    $cost = $incomplete[$mid - 1] * $mid - $prefix[$mid];

                    if ($cost <= $remainingBudget) {
                        $low = $mid;
                    } else {
                        $high = $mid - 1;
                    }
                }

                $count = $low;
                $minimum = intdiv(
                    $remainingBudget + $prefix[$count],
                    $count
                );
                $minimum = min($minimum, $target - 1);

                $beauty += $minimum * $partial;
            }

            $answer = max($answer, $beauty);

            if ($completed < $m) {
                $index = $m - 1 - $completed;
                $completionCost += $target - $incomplete[$index];
            }
        }

        return $answer;
    }
}
