    function minDays($grid) {
        $m = count($grid);
        $n = count($grid[0]);

        $countIslands = function ($board) use ($m, $n) {
            $islands = 0;

            for ($row = 0; $row < $m; $row++) {
                for ($col = 0; $col < $n; $col++) {
                    if ($board[$row][$col] === 0) {
                        continue;
                    }

                    $islands++;

                    if ($islands > 1) {
                        return $islands;
                    }

                    $board[$row][$col] = 0;
                    $stack = [$row * $n + $col];

                    while (!empty($stack)) {
                        $position = array_pop($stack);
                        $currentRow = intdiv($position, $n);
                        $currentCol = $position % $n;

                        if ($currentRow > 0 && $board[$currentRow - 1][$currentCol] === 1) {
                            $board[$currentRow - 1][$currentCol] = 0;
                            $stack[] = ($currentRow - 1) * $n + $currentCol;
                        }

                        if ($currentRow + 1 < $m && $board[$currentRow + 1][$currentCol] === 1) {
                            $board[$currentRow + 1][$currentCol] = 0;
                            $stack[] = ($currentRow + 1) * $n + $currentCol;
                        }

                        if ($currentCol > 0 && $board[$currentRow][$currentCol - 1] === 1) {
                            $board[$currentRow][$currentCol - 1] = 0;
                            $stack[] = $currentRow * $n + $currentCol - 1;
                        }

                        if ($currentCol + 1 < $n && $board[$currentRow][$currentCol + 1] === 1) {
                            $board[$currentRow][$currentCol + 1] = 0;
                            $stack[] = $currentRow * $n + $currentCol + 1;
                        }
                    }
                }
            }

            return $islands;
        };

        if ($countIslands($grid) !== 1) {
            return 0;
        }

        for ($row = 0; $row < $m; $row++) {
            for ($col = 0; $col < $n; $col++) {
                if ($grid[$row][$col] === 0) {
                    continue;
                }

                $grid[$row][$col] = 0;

                if ($countIslands($grid) !== 1) {
                    return 1;
                }

                $grid[$row][$col] = 1;
            }
        }

        return 2;
    }
}
