    /**
     * @param String[] $stickers
     * @param String $target
     * @return Integer
     */
    function minStickers($stickers, $target) {
        $targetLength = strlen($target);
        $targetCounts = array_fill(0, 26, 0);
        $letterMasks = array_fill(0, 26, 0);

        for ($i = 0; $i < $targetLength; $i++) {
            $letter = ord($target[$i]) - 97;
            $targetCounts[$letter]++;
            $letterMasks[$letter] |= (1 << $i);
        }

        $rawCounts = [];
        $coveredLetters = array_fill(0, 26, false);

        foreach ($stickers as $sticker) {
            $counts = array_fill(0, 26, 0);
            $useful = false;

            for ($i = 0, $length = strlen($sticker); $i < $length; $i++) {
                $letter = ord($sticker[$i]) - 97;

                if ($targetCounts[$letter] > 0) {
                    $counts[$letter]++;
                    $coveredLetters[$letter] = true;
                    $useful = true;
                }
            }

            if ($useful) {
                $rawCounts[] = $counts;
            }
        }

        for ($letter = 0; $letter < 26; $letter++) {
            if ($targetCounts[$letter] > 0 && !$coveredLetters[$letter]) {
                return -1;
            }
        }

        $stickerCounts = [];
        $rawLength = count($rawCounts);

        for ($i = 0; $i < $rawLength; $i++) {
            $dominated = false;

            for ($j = 0; $j < $rawLength; $j++) {
                if ($i === $j) {
                    continue;
                }

                $notGreater = true;
                $strictlySmaller = false;

                for ($letter = 0; $letter < 26; $letter++) {
                    if ($rawCounts[$i][$letter] > $rawCounts[$j][$letter]) {
                        $notGreater = false;
                        break;
                    }

                    if ($rawCounts[$i][$letter] < $rawCounts[$j][$letter]) {
                        $strictlySmaller = true;
                    }
                }

                if ($notGreater && ($strictlySmaller || $j < $i)) {
                    $dominated = true;
                    break;
                }
            }

            if (!$dominated) {
                $stickerCounts[] = $rawCounts[$i];
            }
        }

        $sparseStickers = [];
        $candidates = array_fill(0, 26, []);

        foreach ($stickerCounts as $counts) {
            $sparse = [];

            for ($letter = 0; $letter < 26; $letter++) {
                if ($counts[$letter] > 0) {
                    $sparse[] = [$letter, $counts[$letter]];
                }
            }

            $index = count($sparseStickers);
            $sparseStickers[] = $sparse;

            foreach ($sparse as $pair) {
                $candidates[$pair[0]][] = $index;
            }
        }

        $fullMask = (1 << $targetLength) - 1;
        $infinity = 1000000000;
        $dp = array_fill(0, $fullMask + 1, $infinity);
        $dp[0] = 0;

        for ($mask = 0; $mask < $fullMask; $mask++) {
            if ($dp[$mask] === $infinity) {
                continue;
            }

            $firstMissing = 0;
            while (($mask & (1 << $firstMissing)) !== 0) {
                $firstMissing++;
            }

            $requiredLetter = ord($target[$firstMissing]) - 97;

            foreach ($candidates[$requiredLetter] as $stickerIndex) {
                $nextMask = $mask;

                foreach ($sparseStickers[$stickerIndex] as $pair) {
                    $letter = $pair[0];
                    $remaining = $pair[1];
                    $available = $letterMasks[$letter] & (~$nextMask);

                    while ($remaining > 0 && $available !== 0) {
                        $bit = $available & (-$available);
                        $nextMask |= $bit;
                        $available ^= $bit;
                        $remaining--;
                    }
                }

                if ($nextMask !== $mask && $dp[$nextMask] > $dp[$mask] + 1) {
                    $dp[$nextMask] = $dp[$mask] + 1;
                }
            }
        }

        return $dp[$fullMask] === $infinity ? -1 : $dp[$fullMask];
    }
