    /**
     * @param String[] $grid
     * @return Integer
     */
    function regionsBySlashes($grid) {
        $n = count($grid);
        $size = $n * 3;
        $blocked = array_fill(0, $size, array_fill(0, $size, false));

        for ($row = 0; $row < $n; $row++) {
            for ($col = 0; $col < $n; $col++) {
                $ch = $grid[$row][$col];
                $baseRow = $row * 3;
                $baseCol = $col * 3;

                if ($ch === '/') {
                    $blocked[$baseRow][$baseCol + 2] = true;
                    $blocked[$baseRow + 1][$baseCol + 1] = true;
                    $blocked[$baseRow + 2][$baseCol] = true;
                } elseif ($ch === '\\') {
                    $blocked[$baseRow][$baseCol] = true;
                    $blocked[$baseRow + 1][$baseCol + 1] = true;
                    $blocked[$baseRow + 2][$baseCol + 2] = true;
                }
            }
        }

        $regions = 0;
        $dr = [-1, 1, 0, 0];
        $dc = [0, 0, -1, 1];

        for ($row = 0; $row < $size; $row++) {
            for ($col = 0; $col < $size; $col++) {
                if ($blocked[$row][$col]) {
                    continue;
                }

                $regions++;
                $blocked[$row][$col] = true;
                $queue = [$row * $size + $col];
                $head = 0;

                while ($head < count($queue)) {
                    $position = $queue[$head++];
                    $currentRow = intdiv($position, $size);
                    $currentCol = $position % $size;

                    for ($direction = 0; $direction < 4; $direction++) {
                        $nextRow = $currentRow + $dr[$direction];
                        $nextCol = $currentCol + $dc[$direction];

                        if (
                            $nextRow >= 0 && $nextRow < $size &&
                            $nextCol >= 0 && $nextCol < $size &&
                            !$blocked[$nextRow][$nextCol]
                        ) {
                            $blocked[$nextRow][$nextCol] = true;
                            $queue[] = $nextRow * $size + $nextCol;
                        }
                    }
                }
            }
        }

        return $regions;
    }
}
