class StreamChecker {
    private $next = [];
    private $terminal = [];
    private $stream = '';
    private $maxLength = 0;
    private $nodeCount = 1;

    /**
     * @param String[] $words
     */
    function __construct($words) {
        foreach ($words as $word) {
            $length = strlen($word);
            $this->maxLength = max($this->maxLength, $length);
            $node = 0;

            for ($i = $length - 1; $i >= 0; $i--) {
                $charIndex = ord($word[$i]) - 97;
                $edgeKey = $node * 26 + $charIndex;

                if (!isset($this->next[$edgeKey])) {
                    $this->next[$edgeKey] = $this->nodeCount++;
                }

                $node = $this->next[$edgeKey];
            }

            $this->terminal[$node] = true;
        }
    }

    /**
     * @param String $letter
     * @return Boolean
     */
    function query($letter) {
        $this->stream .= $letter;

        if (strlen($this->stream) > $this->maxLength) {
            $this->stream = substr($this->stream, -$this->maxLength);
        }

        $node = 0;

        for ($i = strlen($this->stream) - 1; $i >= 0; $i--) {
            $charIndex = ord($this->stream[$i]) - 97;
            $edgeKey = $node * 26 + $charIndex;

            if (!isset($this->next[$edgeKey])) {
                return false;
            }

            $node = $this->next[$edgeKey];

            if (isset($this->terminal[$node])) {
                return true;
            }
        }

        return false;
    }
}
