    function removeInvalidParentheses($s) {
        $results = [];

        $dfs = function ($str, $scanStart, $removeStart, $open, $close) use (&$dfs, &$results) {
            $balance = 0;
            $length = strlen($str);

            for ($i = $scanStart; $i < $length; $i++) {
                if ($str[$i] === $open) {
                    $balance++;
                } elseif ($str[$i] === $close) {
                    $balance--;
                }

                if ($balance >= 0) {
                    continue;
                }

                for ($j = $removeStart; $j <= $i; $j++) {
                    if (
                        $str[$j] === $close &&
                        ($j === $removeStart || $str[$j - 1] !== $close)
                    ) {
                        $next = substr($str, 0, $j) . substr($str, $j + 1);
                        $dfs($next, $i, $j, $open, $close);
                    }
                }

                return;
            }

            $reversed = strrev($str);

            if ($open === '(') {
                $dfs($reversed, 0, 0, ')', '(');
            } else {
                $results[$reversed] = true;
            }
        };

        $dfs($s, 0, 0, '(', ')');

        return array_keys($results);
    }
