class Solution {
    private $nums;
    private $factor;
    private $expired;
    private $low;
    private $high;
    private $lowSize;
    private $highSize;

    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Float[]
     */
    function medianSlidingWindow($nums, $k) {
        $this->nums = $nums;
        $this->factor = count($nums) + 1;
        $this->expired = -1;
        $this->lowSize = 0;
        $this->highSize = 0;

        $this->low = new SplPriorityQueue();
        $this->high = new SplPriorityQueue();
        $this->low->setExtractFlags(SplPriorityQueue::EXTR_DATA);
        $this->high->setExtractFlags(SplPriorityQueue::EXTR_DATA);

        for ($i = 0; $i < $k; $i++) {
            $this->add($i);
        }

        $result = [$this->getMedian($k)];

        $n = count($nums);
        for ($i = $k; $i < $n; $i++) {
            $this->remove($i - $k);
            $this->add($i);
            $result[] = $this->getMedian($k);
        }

        return $result;
    }

    private function key($index) {
        return $this->nums[$index] * $this->factor + $index;
    }

    private function add($index) {
        $key = $this->key($index);
        $this->pruneLow();

        if ($this->low->isEmpty()) {
            $this->low->insert($index, $key);
            $this->lowSize++;
        } else {
            $lowTop = $this->low->top();

            if ($key <= $this->key($lowTop)) {
                $this->low->insert($index, $key);
                $this->lowSize++;
            } else {
                $this->high->insert($index, -$key);
                $this->highSize++;
            }
        }

        $this->rebalance();
    }

    private function remove($index) {
        $this->pruneLow();

        $key = $this->key($index);
        $lowTop = $this->low->top();

        if ($key <= $this->key($lowTop)) {
            $this->lowSize--;
        } else {
            $this->highSize--;
        }

        $this->expired = $index;
        $this->pruneLow();
        $this->pruneHigh();
        $this->rebalance();
    }

    private function rebalance() {
        $this->pruneLow();
        $this->pruneHigh();

        while ($this->lowSize > $this->highSize + 1) {
            $this->pruneLow();
            $index = $this->low->extract();

            $this->lowSize--;
            $this->high->insert($index, -$this->key($index));
            $this->highSize++;
        }

        while ($this->lowSize < $this->highSize) {
            $this->pruneHigh();
            $index = $this->high->extract();

            $this->highSize--;
            $this->low->insert($index, $this->key($index));
            $this->lowSize++;
        }

        $this->pruneLow();
        $this->pruneHigh();
    }

    private function pruneLow() {
        while (!$this->low->isEmpty() && $this->low->top() <= $this->expired) {
            $this->low->extract();
        }
    }

    private function pruneHigh() {
        while (!$this->high->isEmpty() && $this->high->top() <= $this->expired) {
            $this->high->extract();
        }
    }

    private function getMedian($k) {
        $this->pruneLow();

        $lowIndex = $this->low->top();

        if ($k % 2 === 1) {
            return (float) $this->nums[$lowIndex];
        }

        $this->pruneHigh();
        $highIndex = $this->high->top();

        return ($this->nums[$lowIndex] + $this->nums[$highIndex]) / 2.0;
    }
}
