    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Boolean
     */
    function canPartitionKSubsets($nums, $k) {
        $sum = array_sum($nums);

        if ($sum % $k !== 0) {
            return false;
        }

        $target = intdiv($sum, $k);
        rsort($nums);

        if ($nums[0] > $target) {
            return false;
        }

        $n = count($nums);
        $totalMasks = 1 << $n;
        $dp = array_fill(0, $totalMasks, -1);
        $dp[0] = 0;

        for ($mask = 0; $mask < $totalMasks; $mask++) {
            if ($dp[$mask] === -1) {
                continue;
            }

            for ($i = 0; $i < $n; $i++) {
                $bit = 1 << $i;

                if (($mask & $bit) !== 0) {
                    continue;
                }

                $nextSum = $dp[$mask] + $nums[$i];

                if ($nextSum > $target) {
                    continue;
                }

                $nextMask = $mask | $bit;

                if ($dp[$nextMask] === -1) {
                    $dp[$nextMask] = $nextSum % $target;
                }
            }
        }

        return $dp[$totalMasks - 1] === 0;
    }
}
